import numpy as np
from collections import Counter, defaultdict
els=[]; pos=[]
for l in open('optimized_full.xyz').read().strip().split('\n')[2:]:
    p=l.split(); els.append(p[0]); pos.append([float(x) for x in p[1:4]])
pos=np.array(pos); n=len(els)
print('atom count:', n, Counter(els))
# bond graph
cov={'H':0.31,'C':0.76,'N':0.71,'Ga':1.22,'Ni':1.24}
bonds=defaultdict(list)
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(pos[i]-pos[j])
        if d < cov[els[i]]+cov[els[j]]+0.45:
            bonds[i].append(j)
def nb(i,el): return sum(1 for j in bonds[i] if els[j]==el)
issues=[]
# Ni coordination
ni=[i for i,e in enumerate(els) if e=='Ni'][0]
print('Ni bound to:', [(j,els[j],round(np.linalg.norm(pos[j]-pos[ni]),2)) for j in bonds[ni]])
# each Ga bound to Ni?
for i,e in enumerate(els):
    if e=='Ga' and ni not in bonds[i]: issues.append(f'Ga{i} not bound to Ni')
# methyl carbons have 3H
for i,e in enumerate(els):
    if e=='C':
        nh=nb(i,'H'); nC=nb(i,'C'); nN=nb(i,'N'); nGa=nb(i,'Ga')
        if nh==3 and nC>=1: pass
        elif nh==2 and nC==1: pass  # CH2
        elif nh==0: pass
        else: issues.append(f'C{i}: H={nh} C={nC} N={nN} Ga={nGa}')
# N atoms
for i,e in enumerate(els):
    if e=='N':
        print(f'N{i} bonds:', [(j,els[j],round(np.linalg.norm(pos[j]-pos[i]),2)) for j in bonds[i]])
# close contacts between non-bonded
bad=0
for i in range(n):
    for j in range(i+1,n):
        if j in bonds[i]: continue
        d=np.linalg.norm(pos[i]-pos[j])
        if d < (1.4 if not (els[i]=='H' and els[j]=='H') else 1.1):
            bad+=1
            if bad<15: print('close nonbonded:',i,els[i],j,els[j],round(d,2))
print('close nonbonded count:',bad)
print('ISSUES:',issues if issues else 'none')
# C-H bond length sanity
chs=[np.linalg.norm(pos[i]-pos[j]) for i in range(n) if els[i]=='C' for j in bonds[i] if els[j]=='H']
print('C-H min/max:', round(min(chs),3), round(max(chs),3))
